import React, { useState, useEffect } from 'react';

const App = () => {
    const [backendMessage, setBackendMessage] = useState('');
    const [loading, setLoading] = useState(false);
    const [error, setError] = useState('');
    const [status, setStatus] = useState('');

    const fetchHelloFromBackend = async () => {
        setLoading(true);
        setError('');
        try {
            const response = await fetch('http://localhost:8000/api/hello');
            if (!response.ok) {
                throw new Error(`HTTP error! status: ${response.status}`);
            }
            const data = await response.json();
            setBackendMessage(data.message);
            setStatus('Connected to FastAPI backend successfully!');
        } catch (err) {
            setError(`Failed to connect to backend: ${err.message}`);
            setBackendMessage('');
        } finally {
            setLoading(false);
        }
    };

    const fetchStatus = async () => {
        try {
            const response = await fetch('http://localhost:8000/api/status');
            if (response.ok) {
                const data = await response.json();
                setStatus(`Backend Status: ${data.status} - ${data.message}`);
            }
        } catch (err) {
            setStatus('Backend not connected');
        }
    };

    useEffect(() => {
        fetchStatus();
    }, []);

    return (
        <div style={{ padding: '20px', fontFamily: 'Arial, sans-serif' }}>
            <h1>React + FastAPI Integration</h1>

            <div style={{ marginBottom: '20px', padding: '10px', backgroundColor: '#f0f0f0', borderRadius: '5px' }}>
                <h2>Frontend (React)</h2>
                <p>✅ React app is running on http://localhost:3000</p>
            </div>

            <div style={{ marginBottom: '20px', padding: '10px', backgroundColor: '#e8f5e8', borderRadius: '5px' }}>
                <h2>Backend Status</h2>
                <p>{status || 'Checking backend connection...'}</p>
            </div>

            <div style={{ marginBottom: '20px' }}>
                <button 
                    onClick={fetchHelloFromBackend} 
                    disabled={loading}
                    style={{
                        padding: '10px 20px',
                        fontSize: '16px',
                        backgroundColor: '#007bff',
                        color: 'white',
                        border: 'none',
                        borderRadius: '5px',
                        cursor: loading ? 'not-allowed' : 'pointer'
                    }}
                >
                    {loading ? 'Loading...' : 'Get Hello from FastAPI'}
                </button>
            </div>

            {backendMessage && (
                <div style={{ 
                    padding: '15px', 
                    backgroundColor: '#d4edda', 
                    border: '1px solid #c3e6cb',
                    borderRadius: '5px',
                    marginBottom: '20px'
                }}>
                    <h3>✅ Success!</h3>
                    <p><strong>Backend Response:</strong> {backendMessage}</p>
                </div>
            )}

            {error && (
                <div style={{ 
                    padding: '15px', 
                    backgroundColor: '#f8d7da', 
                    border: '1px solid #f5c6cb',
                    borderRadius: '5px',
                    marginBottom: '20px'
                }}>
                    <h3>❌ Error</h3>
                    <p>{error}</p>
                    <p><em>Make sure the FastAPI backend is running on http://localhost:8000</em></p>
                </div>
            )}

            <div style={{ marginTop: '30px', padding: '15px', backgroundColor: '#fff3cd', borderRadius: '5px' }}>
                <h3>🚀 Next Steps</h3>
                <ul>
                    <li>✅ Basic React + FastAPI integration working</li>
                    <li>🔄 Add authentication & authorization</li>
                    <li>🍪 Implement cookie management</li>
                    <li>🗄️ Add database integration</li>
                    <li>👤 Create user management system</li>
                </ul>
            </div>
        </div>
    );
};

export default App;
